-- Finance accounts cell (finance-accounts), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA finance_accounts;

CREATE FUNCTION finance_accounts.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE finance_accounts.accounts (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    account_type             text NOT NULL CHECK (account_type IN ('bank', 'cash', 'wallet', 'payment', 'credit', 'investment', 'receivable', 'other')),
    owner_scope              text NOT NULL DEFAULT 'personal' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    institution              text,
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'paused', 'closed')),
    opening_balance          double precision,
    opened_on                date,
    closed_on                date,
    metadata                 jsonb CHECK (metadata IS NULL OR (jsonb_typeof(metadata) = 'object')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, name, owner_scope)
);
CREATE UNIQUE INDEX accounts_legacy ON finance_accounts.accounts (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX accounts_account_type ON finance_accounts.accounts (workspace_id, account_type);
CREATE INDEX accounts_owner_scope ON finance_accounts.accounts (workspace_id, owner_scope);
CREATE INDEX accounts_status ON finance_accounts.accounts (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE finance_accounts.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('account')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE finance_accounts.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON finance_accounts.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['accounts', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE finance_accounts.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE finance_accounts.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON finance_accounts.%I'
                       ' USING (workspace_id = finance_accounts.current_workspace())'
                       ' WITH CHECK (workspace_id = finance_accounts.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA finance_accounts TO finance_accounts_api;
GRANT EXECUTE ON FUNCTION finance_accounts.current_workspace() TO finance_accounts_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON finance_accounts.accounts TO finance_accounts_api;
GRANT USAGE ON SEQUENCE finance_accounts.accounts_id_seq TO finance_accounts_api;
GRANT SELECT, INSERT ON finance_accounts.create_keys TO finance_accounts_api;
GRANT SELECT, INSERT ON finance_accounts.outbox TO finance_accounts_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON finance_accounts.outbox TO finance_accounts_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON finance_accounts.outbox TO finance_accounts_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA finance_accounts TO finance_accounts_publisher;
GRANT SELECT ON finance_accounts.outbox TO finance_accounts_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON finance_accounts.outbox TO finance_accounts_publisher;
